// R39: React's exact SDK first-commit signal means handlers attached, not a
// domain write succeeded. Keep the event in the window and every other rule.
// Only the producer's exact name + empty-object payload has this contract;
// prefixes, custom payloads and generic hydration names remain app claims.
const successSignals = events
    .filter((e) => e.type === EventType.SIGNAL)
    .filter((e) => {
    const payload = e.data['data'];
    return !(e.data['name'] === RETICLE_HYDRATION_SIGNAL &&
        payload !== null && typeof payload === 'object' &&
        !Array.isArray(payload) && Object.keys(payload).length === 0);
})
    .map((e) => asString(e.data['name']) ?? 'signal')
    .filter((name) => !ACKNOWLEDGED.test(name));
